class SanitizedSourceMapPlugin {
  apply(compiler: WebpackCompiler) {
    compiler.hooks.afterEmit.tap(
      "SanitizedSourceMapPlugin",
      (compilation: Compilation) => {
        const outputPath = compiler.options.output.path;
        if (!outputPath) return;
        for (const asset of Object.keys(compilation.assets)) {
          if (!asset.endsWith(".js")) continue;
          writeFileSync(
            join(outputPath, `${asset}.map`),
            JSON.stringify({
              version: 3,
              file: asset,
              sources: [],
              names: [],
              mappings: "",
            }),
          );
        }
      },
    );
  }
}

const createGenericConfig = (options: Partial<RspackOptions>) => {
  const def = {
    devtool: false,
    mode: "development" as Mode,
    resolve: {
      extensions: [".ts", ".js"],
    },
    module: {
      rules: [tsloader],
      parser: {
        javascript: {
          overrideStrict: "non-strict",
          dynamicImportMode: "eager",
        },
      },
    },
    optimization: {
      minimizer: [
        new rspack.SwcJsMinimizerRspackPlugin({
          minimizerOptions: {
            module: options.output?.libraryTarget === "module",
          },
        }),
      ],
    },
  };
  const merged = deepmerge<RspackOptions>(
    def as unknown as RspackOptions,
    options,
  );
  merged.plugins = [
    ...(merged.plugins || []),
    ...(rsDoctorPlugin ? [rsDoctorPlugin] : []),
    new SanitizedSourceMapPlugin(),
  ];
  return defineConfig(merged);
};

type RuntimeKitBuildConfig = {
  entry: RspackOptions["entry"];
  output: RspackOptions["output"];
  rewriterWasm: string;
  extraConfig?: Partial<RspackOptions>;
  name: string;
};
// Common configuration options for runtimekit builds
const createRuntimeKitConfig = (options: RuntimeKitBuildConfig) => {
  const { entry, output, rewriterWasm, extraConfig = {}, name } = options;

  return createGenericConfig({
    name,
    entry,
    resolve: {
      alias: {
        "@rewriters": join(runtimekitdir, "src/shared/rewriters"),
        "@client": join(runtimekitdir, "src/client"),
        "@": join(runtimekitdir, "src"),
      },
    },
    output,
    plugins: [
      // new TsCheckerRspackPlugin({
      // 	typescript: {
      // 		configFile: resolve(runtimekitdir, "tsconfig.json"),
      // 	},
      // }),
      new rspack.ProvidePlugin({
        dbg: [join(runtimekitdir, "src/log.ts"), "default"],
      }),
      new rspack.DefinePlugin({
        REWRITERWASM: rewriterWasm,
      }),
      new rspack.DefinePlugin({
        VERSION: JSON.stringify(sjpackagemeta.version),
      }),
      new rspack.DefinePlugin({
        COMMITHASH: (() => {
          try {
            const hash = JSON.stringify(
              execSync("git rev-parse --short HEAD", {
                encoding: "utf-8",
              }).replace(/\r?\n|\r/g, ""),
            );

            return hash;
          } catch {
            return JSON.stringify("unknown");
          }
        })(),
      }),
      new rspack.DefinePlugin({
        BUILDDATE: JSON.stringify(new Date().toISOString()),
      }),
    ],
    target: "webworker",
    ignoreWarnings: [
      {
        module: /src\/entry\.ts/,
        message:
          /Critical dependency: the request of a dependency is an expression/,
      },
    ],
    ...extraConfig,
  });
};

